export function guideArgv(opts: { topic?: string; } = {}): string[] {
  const argv = ["guide"];
  if (opts.topic != null) argv.push(String(opts.topic).trim());
  argv.push("--json");
  return argv;
}

export function opListArgv(opts: { id?: string; tail?: number; } = {}): string[] {
  const argv = ["op", "list"];
  option(argv, "--id", opts.id);
  option(argv, "--tail", opts.tail);
  argv.push("--json");
  return argv;
}

export function opResultArgv(opts: { requestId: string; pid?: number; processStartUtc?: string; key?: string; requestFile?: string; }): string[] {
  const argv = ["op", "result"];
  argv.push(value(opts.requestId, "op result", "requestId"));
  option(argv, "--pid", opts.pid);
  option(argv, "--process-start-utc", opts.processStartUtc);
  option(argv, "--key", opts.key);
  option(argv, "--request-file", opts.requestFile);
  argv.push("--json");
  return argv;
}

export function opStatusArgv(opts: { key: string; id?: string; }): string[] {
  const argv = ["op", "status"];
  argv.push(value(opts.key, "op status", "key"));
  option(argv, "--id", opts.id);
  argv.push("--json");
  return argv;
}

export function sessionHrArgv(opts: { id?: string; restart?: boolean; dropDocs?: boolean; timeoutSeconds?: number; requestFile?: string; } = {}): string[] {
  const argv = ["session", "hr"];
  option(argv, "--id", opts.id);
  if (opts.restart) argv.push("--restart");
  if (opts.dropDocs) argv.push("--drop-docs");
  option(argv, "--timeout-seconds", opts.timeoutSeconds);
  option(argv, "--request-file", opts.requestFile);
  argv.push("--json");
  return argv;
}

export function sessionListArgv(opts: { id?: string; all?: boolean; } = {}): string[] {
  const argv = ["session", "list"];
  option(argv, "--id", opts.id);
  if (opts.all) argv.push("--all");
  argv.push("--json");
  return argv;
}

export function sessionLogsArgv(opts: { id?: string; tail?: number; } = {}): string[] {
  const argv = ["session", "logs"];
  option(argv, "--id", opts.id);
  option(argv, "--tail", opts.tail);
  argv.push("--json");
  return argv;
}

export function sessionStartArgv(opts: { project?: string; year?: string; id?: string; snapshot?: boolean; installed?: boolean; doc?: string; detach?: boolean; conflictPolicy?: string; quarantine?: boolean; background?: boolean; plan?: boolean; timeoutSeconds?: number; requestFile?: string; } = {}): string[] {
  const argv = ["session", "start"];
  option(argv, "--project", opts.project);
  option(argv, "--year", opts.year);
  option(argv, "--id", opts.id);
  if (opts.snapshot) argv.push("--snapshot");
  if (opts.installed) argv.push("--installed");
  option(argv, "--doc", opts.doc);
  if (opts.detach) argv.push("--detach");
  option(argv, "--conflict-policy", opts.conflictPolicy);
  if (opts.quarantine) argv.push("--quarantine");
  if (opts.background) argv.push("--background");
  if (opts.plan) argv.push("--plan");
  option(argv, "--timeout-seconds", opts.timeoutSeconds);
  option(argv, "--request-file", opts.requestFile);
  argv.push("--json");
  return argv;
}

export function sessionStopArgv(opts: { id?: string; force?: boolean; requestFile?: string; } = {}): string[] {
  const argv = ["session", "stop"];
  option(argv, "--id", opts.id);
  if (opts.force) argv.push("--force");
  option(argv, "--request-file", opts.requestFile);
  argv.push("--json");
  return argv;
}

export function testArgv(opts: { plan?: boolean; project?: string; year?: string; filter?: string; attach?: boolean; id?: string; noBuild?: boolean; timeoutSeconds?: number; } = {}): string[] {
  const argv = ["test"];
  if (opts.plan) argv.push("--plan");
  option(argv, "--project", opts.project);
  option(argv, "--year", opts.year);
  option(argv, "--filter", opts.filter);
  if (opts.attach) argv.push("--attach");
  option(argv, "--id", opts.id);
  if (opts.noBuild) argv.push("--no-build");
  option(argv, "--timeout-seconds", opts.timeoutSeconds);
  argv.push("--json");
  return argv;
}

export function versionArgv(): string[] {
  const argv = ["version"];
  argv.push("--json");
  return argv;
}

function value(value: string | number | undefined, verb: string, name: string): string {
  const text = value == null ? "" : String(value).trim();
  if (!text) throw new Error(`${verb} requires ${name}`);
  return text;
}

function option(argv: string[], flag: string, value: string | number | undefined): void {
  if (value != null && String(value).trim()) argv.push(flag, String(value).trim());
}
